I’m building a standard-library-only Python parser for a plain-text outline. Each nonblank line has a nonblank label preceded by an exact multiple of two spaces. Tabs are forbidden, the first line must be at depth zero, and depth may increase by at most one from the preceding line. Preserve sibling order and reject invalid input with ValueError.

Here’s my implementation:

```python
def parse(text):
    roots = []
    for line in text.splitlines():
        depth = (len(line) - len(line.lstrip(' '))) // 2
        node = {'label': line.strip(), 'children': []}
        if depth == 0:
            roots.append(node)
        else:
            roots[-1]['children'].append(node)
    return roots
```

Examine it against the grammar, including odd indentation, tabs, blank labels, and depth jumps. What does it mishandle?

```python
def parse(text):
    roots = []
    # stack[d] is the most recent node at depth d.
    stack = []

    for line_number, line in enumerate(text.splitlines(), 1):
        if '\t' in line:
            raise ValueError(f'line {line_number}: tabs are forbidden')

        indent = len(line) - len(line.lstrip(' '))
        label = line[indent:]
        if not label.strip():
            raise ValueError(f'line {line_number}: blank label')
        if indent % 2:
            raise ValueError(f'line {line_number}: odd indentation')

        depth = indent // 2
        if depth > len(stack):
            raise ValueError(f'line {line_number}: invalid depth increase')

        node = {'label': label, 'children': []}
        if depth == 0:
            roots.append(node)
        else:
            stack[depth - 1]['children'].append(node)
        stack[depth:] = [node]

    return roots
```

This treats blank or whitespace-only lines as invalid, consistent with the earlier discussion; empty input produces an empty tree. It preserves trailing label whitespace and does not modify the input string.

I’m designing a purely fictional, local equipment-reservation reducer; no real reservation is processed. Each active unit needs 14 cm of decorative ribbon. Events are dictionaries: a create has a type, a unique nonempty string id, and a positive integer quantity; a cancel has a type and id. Identical creates for an ID are idempotent, conflicting reuse must reject, and cancellation before creation establishes a tombstone. Cancellation is idempotent. Malformed events, including boolean quantities, must reject.

My current implementation is:

```python
def reduce_events(events):
    active = {}
    for e in events:
        if e['type'] == 'create':
            active[e['id']] = e['quantity']
        elif e['type'] == 'cancel':
            active.pop(e['id'], None)
    return active
```

Trace a cancellation of `b` followed by its creation, alongside repeated identical creates and then a conflicting create for `a`. Show the state after each event and explain where this implementation violates the rules.

```python
def reduce_events(events):
    creates = {}
    tombstones = set()
    active = {}

    for event in events:
        if not isinstance(event, dict):
            raise ValueError('event must be a dictionary')
        kind = event.get('type')
        if kind == 'create':
            expected = {'type', 'id', 'quantity'}
        elif kind == 'cancel':
            expected = {'type', 'id'}
        else:
            raise ValueError('invalid event type')
        if event.keys() != expected:
            raise ValueError('invalid event fields')

        reservation_id = event['id']
        if not isinstance(reservation_id, str) or not reservation_id:
            raise ValueError('id must be a nonempty string')

        if kind == 'create':
            quantity = event['quantity']
            if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
                raise ValueError('quantity must be a positive integer')
            if reservation_id in creates:
                if creates[reservation_id] != quantity:
                    raise ValueError('conflicting create')
                continue
            creates[reservation_id] = quantity
            if reservation_id not in tombstones:
                active[reservation_id] = quantity
        else:
            tombstones.add(reservation_id)
            active.pop(reservation_id, None)

    return {'creates': creates, 'tombstones': tombstones, 'active': active}
```

The reducer accepts exactly the specified fields. Since `id` and `type` are fixed for each create, retaining its quantity retains the data needed to compare the original payload. Inputs are not modified; a conflict raises `ValueError`, including after cancellation.

The oracle validates and groups events by ID, then derives state from the set of creates and the presence of any cancellation. It does not replay the reducer’s transitions.

```python
from itertools import permutations

# Assumes reduce_events is defined as above.
def oracle(events):
    by_id = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('event must be a dictionary')
        kind = event.get('type')
        if kind not in ('create', 'cancel'):
            raise ValueError('invalid event type')
        fields = {'type', 'id', 'quantity'} if kind == 'create' else {'type', 'id'}
        if set(event) != fields:
            raise ValueError('invalid event fields')
        ident = event['id']
        if not isinstance(ident, str) or not ident:
            raise ValueError('invalid id')
        if kind == 'create':
            q = event['quantity']
            if isinstance(q, bool) or not isinstance(q, int) or q <= 0:
                raise ValueError('invalid quantity')
        by_id.setdefault(ident, []).append(event)

    creates, tombstones, active = {}, set(), {}
    for ident, items in by_id.items():
        quantities = {e['quantity'] for e in items if e['type'] == 'create'}
        if len(quantities) > 1:
            raise ValueError('conflicting creates')
        cancelled = any(e['type'] == 'cancel' for e in items)
        if cancelled:
            tombstones.add(ident)
        if quantities:
            quantity = next(iter(quantities))
            creates[ident] = quantity
            if not cancelled:
                active[ident] = quantity
    return {'creates': creates, 'tombstones': tombstones, 'active': active}

trace = [
    {'type': 'create', 'id': 'a', 'quantity': 2},
    {'type': 'create', 'id': 'a', 'quantity': 2},
    {'type': 'cancel', 'id': 'a'},
    {'type': 'create', 'id': 'b', 'quantity': 1},
]
expected = {'creates': {'a': 2, 'b': 1}, 'tombstones': {'a'}, 'active': {'b': 1}}
for ordering in permutations(trace):
    assert oracle(ordering) == expected
    assert reduce_events(ordering) == expected

bad_traces = [
    [{'type': 'create', 'id': 'a', 'quantity': True}],
    [{'type': 'create', 'id': '', 'quantity': 1}],
    [{'type': 'cancel', 'id': 'a', 'extra': 1}],
    [{'type': 'unknown', 'id': 'a'}],
    [{'type': 'create', 'id': 'a', 'quantity': 2},
     {'type': 'cancel', 'id': 'a'},
     {'type': 'create', 'id': 'a', 'quantity': 3}],
]
for events in bad_traces:
    for fn in (oracle, reduce_events):
        try:
            fn(events)
        except ValueError:
            pass
        else:
            raise AssertionError(f'{fn.__name__} accepted {events!r}')
```

The permutations cover cancellation both before and after creation; the explicit expected state also guards against both implementations agreeing on the same wrong result.

I want pure, standard-library Python functions for run-length groups and offsets in a string. Groups represent consecutive equal characters, including spaces; positions count Python Unicode code points, not bytes or grapheme clusters. Here’s my current code:

```python
def groups(text):
    counts = {}
    for ch in text:
        counts[ch] = counts.get(ch, 0) + 1
    return list(counts.items())
```

Use a concrete string with a space and a nonadjacent repeated character to demonstrate the output this code gives and the groups it should give. Explain what happens to the original order and group boundaries.

```python
def encode(text):
    if not isinstance(text, str):
        raise ValueError('text must be a string')
    result = []
    for ch in text:
        if result and result[-1][0] == ch:
            previous, count = result[-1]
            result[-1] = (previous, count + 1)
        else:
            result.append((ch, 1))
    return result


def decode(groups):
    try:
        iterator = iter(groups)
    except TypeError as exc:
        raise ValueError('groups must be iterable') from exc

    parts = []
    for group in iterator:
        if not isinstance(group, (tuple, list)) or len(group) != 2:
            raise ValueError('each group must be a character/count pair')
        ch, count = group
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError('character must be one Unicode code point')
        if isinstance(count, bool) or not isinstance(count, int) or count <= 0:
            raise ValueError('count must be a positive integer')
        parts.append(ch * count)
    return ''.join(parts)
```

`encode('')` returns `[]`, and `decode([])` returns `''`. Adjacent equal-character groups are accepted in order: `decode([('a', 1), ('a', 2)])` returns `'aaa'`.

```python
def locate(groups, offset):
    """Return (group index, offset within group) for a character offset."""
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('offset must be a nonnegative integer')

    # Validate all groups, even if the requested position appears early.
    validated = []
    try:
        iterator = iter(groups)
    except TypeError as exc:
        raise ValueError('groups must be iterable') from exc
    for group in iterator:
        if not isinstance(group, (tuple, list)) or len(group) != 2:
            raise ValueError('each group must be a character/count pair')
        ch, count = group
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError('character must be one Unicode code point')
        if isinstance(count, bool) or not isinstance(count, int) or count <= 0:
            raise ValueError('count must be a positive integer')
        validated.append((ch, count))

    remaining = offset
    for index, (_, count) in enumerate(validated):
        if remaining < count:
            return index, remaining
        remaining -= count
    raise ValueError('offset is outside the encoding')


# Explicit positions in 'aaa b': adjacent 'a' groups stay distinct.
groups = [('a', 1), ('a', 2), (' ', 1), ('b', 1)]
expected = [(0, 0), (1, 0), (1, 1), (2, 0), (3, 0)]
for offset, location in enumerate(expected):
    assert locate(groups, offset) == location

for bad_groups, bad_offset in [
    (groups, -1), (groups, 5), (groups, 6),
    ([], 0), (groups, True), (groups, 1.5),
    ([('a', 1), ('b', 0)], 0),
]:
    try:
        locate(bad_groups, bad_offset)
    except ValueError:
        pass
    else:
        raise AssertionError((bad_groups, bad_offset))
```

```python
def split_at_offset(groups, offset, normalize=False):
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('offset must be a nonnegative integer')
    if not isinstance(normalize, bool):
        raise ValueError('normalize must be a boolean')
    try:
        iterator = iter(groups)
    except TypeError as exc:
        raise ValueError('groups must be iterable') from exc

    validated = []
    for group in iterator:
        if not isinstance(group, (tuple, list)) or len(group) != 2:
            raise ValueError('each group must be a character/count pair')
        ch, count = group
        if not isinstance(ch, str) or len(ch) != 1:
            raise ValueError('character must be one Unicode code point')
        if isinstance(count, bool) or not isinstance(count, int) or count <= 0:
            raise ValueError('count must be a positive integer')
        validated.append((ch, count))

    if offset > sum(count for _, count in validated):
        raise ValueError('offset is outside the encoding')

    left, right = [], []
    remaining = offset

    def append(side, ch, count):
        if count == 0:
            return
        if normalize and side and side[-1][0] == ch:
            side[-1] = (ch, side[-1][1] + count)
        else:
            side.append((ch, count))

    for ch, count in validated:
        taken = min(remaining, count)
        append(left, ch, taken)
        append(right, ch, count - taken)
        remaining -= taken
    return left, right


# Uses decode from the earlier implementation.
groups = [('a', 2), ('a', 2), (' ', 1), ('b', 2)]
original = groups.copy()
assert split_at_offset(groups, 3) == (
    [('a', 2), ('a', 1)], [('a', 1), (' ', 1), ('b', 2)])
assert split_at_offset(groups, 2) == (
    [('a', 2)], [('a', 2), (' ', 1), ('b', 2)])
assert split_at_offset(groups, 3, normalize=True) == (
    [('a', 3)], [('a', 1), (' ', 1), ('b', 2)])
assert split_at_offset([], 0) == ([], [])
assert split_at_offset(groups, 0) == ([], original)
assert split_at_offset(groups, 7) == (original, [])

left, right = split_at_offset(groups, 3)
assert decode(left) == 'aaa'
assert decode(right) == 'a bb'
assert decode(left) + decode(right) == 'aaaa bb'
assert groups == original

for bad in (-1, 8, True, 1.5):
    try:
        split_at_offset(groups, bad)
    except ValueError:
        pass
    else:
        raise AssertionError(f'accepted offset {bad!r}')
```
